                "hindi": "<b>(जयमाला)</b><br>जय आदिनाथ जय श्री जिनराज, तुम ने सुधारे भक्तों के काज।<br>तुम प्रथम तीर्थंकर हो महान, तुम ने दिया जग को ज्ञान-दान॥<br>अयोध्या नगरी में जन्म लिया, नृप नाभिराय का मान किया।<br>माता मरुदेवि की कोख सार, तुम अवतरे त्रिभुवन के आधार॥"
