                "hindi": "<div class=\"section-title\">॥ अर्घावली एवं स्थापना ॥</div><br><b>(अर्घावली)</b><br>जल-गंध-अक्षत-पुष्प-चरु, दीप-धूप-फल अर्घ्य करा।<br>तुम को जजों परमेश्वर, भव-भव पार लगा॥<br><br><b>(स्थापना)</b><br>ॐ ह्रीं श्री देव-शास्त्र-गुरुभ्यो नमः! अत्र अवतरत अवतरत संवौषट्! (आह्वाननम्)<br>ॐ ह्रीं श्री देव-शास्त्र-गुरुभ्यो नमः! अत्र तिष्ठत तिष्ठत ठः ठः! (स्थापनम्)<br>ॐ ह्रीं श्री देव-शास्त्र-गुरुभ्यो नमः! अत्र मम सन्निहिता भवत भवत वषट्! (सन्निधिकरणम्)"
