                "hindi": "<b>(अर्घ्य)</b><br>जल-गंध-अक्षत-पुष्प-चरु, दीप-धूप-फल अर्घ्य करा।<br>तुम को जजों परमेश्वर, भव-भव पार लगा॥<br>ॐ ह्रीं श्री देव-शास्त्र-गुरुभ्यो अनर्घ्यपद-प्राप्तये अर्घ्यं निर्वपामीति स्वाहा ॥९॥"
