                "hindi": "<div class=\"section-title\">जयमाला</div><br><p class=\"verse\"><br><strong>दोहा:</strong><br>आदि जिनेश्वर पद नमो, नाभिराज-कुल-भूप।<br>मरुदेवी के लाड़िले, त्रिभुवन-हित-सुख-रूप॥<br></p><br><p class=\"verse\"><br><strong>जयमाला (कविवर बुधजन जी कृत):</strong><br>प्रभु पतित-पावन मैं अपावन, चरण आयो शरण जी।<br>यों विरद आप निहार स्वामी, मेट जामन-मरण जी॥१॥<br><br>तुम ना पिछान्यो आन मान्यो, देव विविध प्रकार जी।<br>या बुद्धि सेती निज न जान्यो, भ्रम गिन्यो हितकार जी॥२॥<br><br>भव-विकट-वन में कर्म बैरी, ज्ञान-धन मेरो हर्यो।<br>सब इष्ट भूल्यो भ्रष्ट होय, अनिष्ट गति धरतो फिर्यो॥३॥<br><br>धन घड़ी यों धन दिवस यों ही, धन्य जनम मेरो भयो।<br>अब भाग्य मेरो उदय आयो, दरश प्रभु को लख लयो॥४॥<br><br>छवि वीतरागी नग्नमुद्रा, दृष्टि-नासा पै धरैं।<br>वसु प्रातिहार्य अनन्त गुण-युत, कोटि रवि छवि को हरैं॥५॥<br><br>मिट गयो तिमिर मिथ्यात्व मेरो, उदय रवि आतम भयो।<br>मो उर हरष ऐसो भयो, मनु रंक चिंतामणि लयो॥६॥<br><br>दोऊ हाथ जोड़ नवाऊँ मस्तक, वीनऊँ तुम चरण जी।<br>सर्वोत्कृष्ट त्रिलोकपति जिन, सुनहुँ तारन-तरण जी॥७॥<br><br>जाचूँ नहीं सुर-वास पुनि नर, राज परिजन साथ जी।<br>'बुध' जाचहूँ तुव भक्ति भव-भव, दीजिए शिवनाथ जी॥८॥<br></p><br><p class=\"verse\"><br><strong>दोहा:</strong><br>आदिनाथ भगवान की, जो पूजा चित लाय।<br>सो पावै सुख शांतियुत, अष्टम-कर्म नशाय॥<br></p><br><div class=\"argh-box\"><br><span class=\"mantra\">ॐ ह्रीं श्रीआदिनाथजिनेन्द्राय जयमाला-पूर्णार्घ्यं निर्वपामीति स्वाहा।</span><br><span class=\"shloka\">इत्याशीर्वादः (पुष्पांजलिं क्षिपेत्)।</span><br></div>"
