                "hindi": "<div class=\"section-title\">॥ श्री अनंतनाथ पंचकल्याणक अर्घावली ॥</div><br><p class=\"verse\"><br><strong>१. गर्भकल्याणक (अयोध्या नगरी):</strong><br>वैशाख-बदी-एकम सुखकार, गर्भ पधारे जग-दातार।<br>मात सर्वयशा उर हरषाई, सुरपति आकर भेंट चढ़ाई॥<br><span class=\"mantra\">ॐ ह्रीं वैशाखकृष्णप्रतिपदायां गर्भकल्याणकमण्डिताय श्रीअनन्तनाथजिनेन्द्राय अर्घ्यं निर्वपामीति स्वाहा।</span><br><br><strong>२. जन्मकल्याणक (अयोध्या नगरी):</strong><br>ज्येष्ठ-बदी-द्वादशी सुखदाय, जन्मे त्रिभुवन-नाथ सुहाय।<br>मेरु-शिखर सुरपति नहवाये, अनंतनाथ प्रभु नाम उचराये॥<br><span class=\"mantra\">ॐ ह्रीं ज्येष्ठकृष्णद्वादश्यां जन्मकल्याणकमण्डिताय श्रीअनन्तनाथजिनेन्द्राय अर्घ्यं निर्वपामीति स्वाहा।</span><br><br><strong>३. तप/दीक्षाकल्याणक (अयोध्या - सहेतुक वन):</strong><br>ज्येष्ठ-बदी-द्वादशी वैरागी, राज-पाट सब तृणवत् त्यागी।<br>सहेतुक-वन में दीक्षा लीनी, आत्म-ध्यान-साधना कीनी॥<br><span class=\"mantra\">ॐ ह्रीं ज्येष्ठकृष्णद्वादश्यां दीक्षाकल्याणकमण्डिताय श्रीअनन्तनाथजिनेन्द्राय अर्घ्यं निर्वपामीति स्वाहा।</span><br><br><strong>४. केवलज्ञानकल्याणक (अश्वत्थ / पीपल वृक्ष):</strong><br>चैत्र-सुदी-चौदस दिन पावन, केवलज्ञान लख्यो मन-भावन।<br>पीपल-वृक्ष तले प्रभु राजे, समवशरण सुर-गण मिलि साजे॥<br><span class=\"mantra\">ॐ ह्रीं चैत्रशुक्लचतुर्दश्यां केवलज्ञानकल्याणकमण्डिताय श्रीअनन्तनाथजिनेन्द्राय अर्घ्यं निर्वपामीति स्वाहा।</span><br><br><strong>५. मोक्षकल्याणक (सम्मेद शिखर जी - स्वयंप्रभ कूट):</strong><br>चैत्र-सुदी-चौदस सुखकारी, पहुँचे सम्मेद शिखर शिव-हारी।<br>स्वयंप्रभ-कूट से सिद्ध सिधाये, कर्म-नाश अक्षय-पद पाये॥<br><span class=\"mantra\">ॐ ह्रीं चैत्रशुक्लचतुर्दश्यां मोक्षकल्याणकमण्डिताय श्रीअनन्तनाथजिनेन्द्राय अर्घ्यं निर्वपामीति स्वाहा।</span><br></p>"
