                "hindi": "<div class=\"section-title\">॥ श्री मुनिसुव्रतनाथ पंचकल्याणक अर्घावली ॥</div><br><p class=\"verse\"><br><strong>१. गर्भकल्याणक (राजगृह नगरी):</strong><br>श्रावण-बदी-दूज सुखकार, गर्भ पधारे जग-दातार।<br>मात पद्मावती उर हरषाई, सुरपति आकर भेंट चढ़ाई॥<br><span class=\"mantra\">ॐ ह्रीं श्रावणकृष्णद्वितीयायां गर्भकल्याणकमण्डिताय श्रीमुनिसुव्रतनाथजिनेन्द्राय अर्घ्यं निर्वपामीति स्वाहा।</span><br><br><strong>२. जन्मकल्याणक (राजगृह नगरी):</strong><br>ज्येष्ठ-बदी-नौमी सुखदाय, जनमे त्रिभुवन-नाथ सुहाय।<br>मेरु-शिखर सुरपति नहवाये, मुनिसुव्रत प्रभु नाम उचराये॥<br><span class=\"mantra\">ॐ ह्रीं ज्येष्ठकृष्णनवम्यां जन्मकल्याणकमण्डिताय श्रीमुनिसुव्रतनाथजिनेन्द्राय अर्घ्यं निर्वपामीति स्वाहा।</span><br><br><strong>३. तप/दीक्षाकल्याणक (राजगृह - नील वन):</strong><br>ज्येष्ठ-बदी-नौमी वैरागी, राज-पाट सब तृणवत् त्यागी।<br>नील-विपिन में दीक्षा लीनी, आत्म-ध्यान-साधना कीनी॥<br><span class=\"mantra\">ॐ ह्रीं ज्येष्ठकृष्णनवम्यां दीक्षाकल्याणकमण्डिताय श्रीमुनिसुव्रतनाथजिनेन्द्राय अर्घ्यं निर्वपामीति स्वाहा।</span><br><br><strong>४. केवलज्ञानकल्याणक (चम्पक वृक्ष):</strong><br>वैशाख-बदी-नौमी दिन पावन, केवलज्ञान लख्यो मन-भावन।<br>चम्पक-वृक्ष तले प्रभु राजे, समवशरण सुर-गण मिलि साजे॥<br><span class=\"mantra\">ॐ ह्रीं वैशाखकृष्णनवम्यां केवलज्ञानकल्याणकमण्डिताय श्रीमुनिसुव्रतनाथजिनेन्द्राय अर्घ्यं निर्वपामीति स्वाहा।</span><br><br><strong>५. मोक्षकल्याणक (सम्मेद शिखर जी - निर्जर कूट):</strong><br>फाल्गुन-बदी-द्वादशी सुखकारी, पहुँचे सम्मेद शिखर शिव-हारी।<br>निर्जर-कूट से सिद्ध सिधाये, कर्म-नाश अक्षय-पद पाये॥<br><span class=\"mantra\">ॐ ह्रीं फाल्गुनकृष्णद्वादश्यां मोक्षकल्याणकमण्डिताय श्रीमुनिसुव्रतनाथजिनेन्द्राय अर्घ्यं निर्वपामीति स्वाहा।</span><br></p>"
