                "hindi": "<div class=\"section-title\">॥ श्री नेमिनाथ पंचकल्याणक अर्घावली ॥</div><br><p class=\"verse\"><br><strong>१. गर्भकल्याणक (शौरीपुर नगरी):</strong><br>कार्तिक-सुदी-छठ मंगलकार, गर्भ पधारे जग-दातार।<br>मात शिवादेवी हरषाई, सुर-नर मिलि जयकार सुनाई॥<br><span class=\"mantra\">ॐ ह्रीं कार्तिकशुक्लषष्ठ्यां गर्भकल्याणकमण्डिताय श्रीनेमिनाथजिनेन्द्राय अर्घ्यं निर्वपामीति स्वाहा।</span><br><br><strong>२. जन्मकल्याणक (शौरीपुर नगरी):</strong><br>सावन-सुदी-छठ के दिन पावन, जनमे त्रिभुवन-मन-भावन।<br>मेरु-शिखर सुरपति नहवाये, नेमि जिनेश्वर नाम उचराये॥<br><span class=\"mantra\">ॐ ह्रीं श्रावणशुक्लषष्ठ्यां जन्मकल्याणकमण्डिताय श्रीनेमिनाथजिनेन्द्राय अर्घ्यं निर्वपामीति स्वाहा।</span><br><br><strong>३. तप/दीक्षाकल्याणक (गिरनार जी - सहस्राम्र वन):</strong><br>सावन-सुदी-छठ पशु-क्रंदन सुनि, राजुल त्यागी बने महा-मुनि।<br>ऊर्जयंत पर दीक्षा लीनी, आत्म-ध्यान-साधना कीनी॥<br><span class=\"mantra\">ॐ ह्रीं श्रावणशुक्लषष्ठ्यां दीक्षाकल्याणकमण्डिताय श्रीनेमिनाथजिनेन्द्राय अर्घ्यं निर्वपामीति स्वाहा।</span><br><br><strong>४. केवलज्ञानकल्याणक (मेषश्रृंग वृक्ष):</strong><br>आश्विन-सुदी-एकम सुखकारी, केवलज्ञान लख्यो अविकारी।<br>मेषश्रृंग तर समवशरण विराजे, दिव्य-ध्वनी भवि-हित में गाजे॥<br><span class=\"mantra\">ॐ ह्रीं आश्विनशुक्लप्रतिपदायां केवलज्ञानकल्याणकमण्डिताय श्रीनेमिनाथजिनेन्द्राय अर्घ्यं निर्वपामीति स्वाहा।</span><br><br><strong>५. मोक्षकल्याणक (ऊर्जयंत पर्वत - गिरनार जी):</strong><br>आषाढ़-सुदी-अष्टमी सुख-दाय, ऊर्जयंत से मुकति सिधाय।<br>पाँचहि टोंक सिद्ध-पद पाये, अष्ट-कर्म नशि शिव-पद छाये॥<br><span class=\"mantra\">ॐ ह्रीं आषाढशुक्लाष्टम्यां मोक्षकल्याणकमण्डिताय श्रीनेमिनाथजिनेन्द्राय अर्घ्यं निर्वपामीति स्वाहा।</span><br></p>"
